function getSuitDisplay(suit, theme) {
  if (theme === "traditional") {
    const map = { H: "♥", D: "♦", S: "♠", C: "♣" };
    return { symbol: map[suit], color: (suit === "H" || suit === "D") ? "#c0392b" : "#1a1a2e" };
  }
  if (theme === "german") {
    const map = { H: "❤️", D: "🔔", S: "🌿", C: "🌰" };
    return { symbol: map[suit], color: (suit === "H") ? "#c0392b" : "#2d5a1b" };
  }
  return null;
}

